"use client";

import { useReducedMotion } from "motion/react";
import { useCallback, useEffect, useId, useRef, useState } from "react";

import {
  ChevronDownIcon,
  PlusIcon,
  SparklesIcon,
} from "@/components/blocks/parts/icons";
import { Button } from "@/components/ui/button";
import {
  DropdownMenu,
  DropdownMenuContent,
  DropdownMenuItem,
  DropdownMenuTrigger,
} from "@/components/ui/dropdown-menu";
import { Tabs, TabsContent, TabsList, TabsTrigger } from "@/components/ui/tabs";

import { BlockFrame } from "../parts/block-frame";
import { FIELDS, FILE_NAME, SCHEMA, toJson } from "./document-extract/data";
import { FieldList } from "./document-extract/field-list";
import { InvoicePage } from "./document-extract/invoice-page";
import { SourceConnector } from "./document-extract/source-connector";
import { FileIcon, MinusIcon } from "./icons";
import type { VarStyle } from "@/components/blocks/lib/css-vars";

type Run = "idle" | "reading" | "done" | "accepted";
const TABS = ["fields", "json", "schema"] as const;
type Tab = (typeof TABS)[number];

const PAGE_WIDTH_REM = 36;
const MIN_ZOOM = 0.4;
const MAX_ZOOM = 2;

/** Builds the curve from the top of a field up to the foot of its source, in the block's coordinates. */
function curveBetween(
  root: DOMRect,
  field: DOMRect,
  source: DOMRect,
  box: DOMRect,
): string {
  const x1 = field.left - root.left + 12;
  const y1 = field.top - root.top;
  const x2 =
    Math.min(Math.max(source.left + source.width / 2, box.left), box.right) -
    root.left;
  const y2 = Math.min(Math.max(source.bottom, box.top), box.bottom) - root.top;
  const bend = Math.max(24, (y1 - y2) / 2);
  return `M ${x1} ${y1} C ${x1} ${y1 - bend}, ${x2} ${y2 + bend}, ${x2} ${y2}`;
}

/**
 * Reads typed fields off an invented invoice. Fields fill in as the page is
 * read. Hovering or focusing a value scrolls the page to where it came from,
 * lights both ends and draws one curve between them. Each value can be
 * confirmed, and Review and Accept all close the run.
 */
export function DocumentExtract({ className }: { className?: string }) {
  const titleId = useId();
  const reduceMotion = useReducedMotion();
  const root = useRef<HTMLDivElement>(null);
  const box = useRef<HTMLDivElement>(null);
  const fieldEls = useRef(new Map<string, HTMLElement>());
  const timers = useRef<ReturnType<typeof setTimeout>[]>([]);

  const [zoom, setZoom] = useState<number | null>(null);
  const [fitZoom, setFitZoom] = useState(1);
  const [run, setRun] = useState<Run>("idle");
  const [filled, setFilled] = useState<Set<string>>(() => new Set());
  const [confirmed, setConfirmed] = useState<Set<string>>(() => new Set());
  const [lit, setLit] = useState<string | null>(null);
  const [path, setPath] = useState<string | null>(null);
  const [tab, setTab] = useState<Tab>("fields");

  const scale = zoom ?? fitZoom;

  const clearTimers = useCallback(() => {
    timers.current.forEach(clearTimeout);
    timers.current = [];
  }, []);
  useEffect(() => clearTimers, [clearTimers]);

  // Fit keeps the page as wide as its box, and follows the box when the card resizes.
  useEffect(() => {
    const element = box.current;
    if (!element) return;
    const observer = new ResizeObserver(() => {
      const rem =
        parseFloat(getComputedStyle(document.documentElement).fontSize) || 16;
      const room = element.clientWidth - rem * 2;
      setFitZoom(
        Math.min(MAX_ZOOM, Math.max(MIN_ZOOM, room / (PAGE_WIDTH_REM * rem))),
      );
    });
    observer.observe(element);
    return () => observer.disconnect();
  }, []);

  const register = useCallback((id: string, element: HTMLElement | null) => {
    if (element) fieldEls.current.set(id, element);
    else fieldEls.current.delete(id);
  }, []);

  const extract = () => {
    clearTimers();
    setFilled(new Set());
    setConfirmed(new Set());
    setLit(null);
    setRun("reading");
    if (reduceMotion) {
      timers.current.push(
        setTimeout(() => {
          setFilled(new Set(FIELDS.map((field) => field.id)));
          setRun("done");
        }, 200),
      );
      return;
    }
    FIELDS.forEach((field, index) => {
      timers.current.push(
        setTimeout(
          () => {
            setFilled((current) => new Set(current).add(field.id));
            if (index === FIELDS.length - 1) setRun("done");
          },
          450 + index * 220,
        ),
      );
    });
  };

  const reset = () => {
    clearTimers();
    setFilled(new Set());
    setConfirmed(new Set());
    setLit(null);
    setRun("idle");
  };

  // Lighting a field scrolls the page box to its source, then keeps the curve on both ends while the box scrolls.
  useEffect(() => {
    const element = box.current;
    if (!lit || !element) return;
    const source = element.querySelector<HTMLElement>(`[data-source="${lit}"]`);
    if (!source) return;
    const boxRect = element.getBoundingClientRect();
    const sourceRect = source.getBoundingClientRect();
    element.scrollTo({
      top:
        element.scrollTop +
        sourceRect.top -
        boxRect.top -
        element.clientHeight / 2 +
        sourceRect.height / 2,
      left:
        element.scrollLeft +
        sourceRect.left -
        boxRect.left -
        element.clientWidth / 2 +
        sourceRect.width / 2,
      behavior: reduceMotion ? "auto" : "smooth",
    });
    let frame = 0;
    const draw = () => {
      cancelAnimationFrame(frame);
      frame = requestAnimationFrame(() => {
        const field = fieldEls.current.get(lit);
        const frameEl = root.current;
        if (!field || !frameEl) return;
        setPath(
          curveBetween(
            frameEl.getBoundingClientRect(),
            field.getBoundingClientRect(),
            source.getBoundingClientRect(),
            element.getBoundingClientRect(),
          ),
        );
      });
    };
    draw();
    element.addEventListener("scroll", draw, { passive: true });
    window.addEventListener("resize", draw);
    return () => {
      cancelAnimationFrame(frame);
      element.removeEventListener("scroll", draw);
      window.removeEventListener("resize", draw);
    };
  }, [lit, scale, reduceMotion]);

  const confirm = (id: string) =>
    setConfirmed((current) => {
      const next = new Set(current);
      if (next.has(id)) next.delete(id);
      else next.add(id);
      return next;
    });

  const review = () => {
    const next = FIELDS.find(
      (field) => filled.has(field.id) && !confirmed.has(field.id),
    );
    if (next) fieldEls.current.get(next.id)?.focus();
  };

  const acceptAll = () => {
    setConfirmed(new Set(filled));
    setRun("accepted");
    setLit(null);
  };

  const status =
    run === "idle"
      ? `${FIELDS.length} fields to fill from this document.`
      : run === "reading"
        ? `Reading the page: ${filled.size} of ${FIELDS.length} fields.`
        : run === "done"
          ? `${filled.size} fields read, ${confirmed.size} confirmed.`
          : `Accepted. ${filled.size} fields saved to Fernhill billing.`;

  const stepZoom = (step: number) =>
    setZoom(
      Math.min(
        MAX_ZOOM,
        Math.max(MIN_ZOOM, Math.round((scale + step) * 10) / 10),
      ),
    );

  const zoomStyle: VarStyle = { "--zoom": String(scale) };
  return (
    <BlockFrame aria-labelledby={titleId} className={className}>
      <div ref={root} className="relative">
        <h2 id={titleId} className="sr-only">
          Extract fields from {FILE_NAME}
        </h2>
        <div className="flex flex-wrap items-center justify-between gap-2 border-b border-border px-3 py-2">
          <DropdownMenu>
            <DropdownMenuTrigger asChild>
              <Button variant="ghost" size="sm" className="min-w-0 max-w-full">
                <FileIcon aria-hidden="true" className="size-4 text-chart-4" />
                <span className="truncate">{FILE_NAME}</span>
                <ChevronDownIcon
                  aria-hidden="true"
                  className="size-4 text-muted-foreground"
                />
              </Button>
            </DropdownMenuTrigger>
            <DropdownMenuContent align="start">
              <DropdownMenuItem onSelect={extract}>
                Read the page again
              </DropdownMenuItem>
              <DropdownMenuItem onSelect={reset}>
                Clear the results
              </DropdownMenuItem>
              <DropdownMenuItem
                onSelect={() =>
                  void navigator.clipboard
                    ?.writeText(FILE_NAME)
                    .catch(() => undefined)
                }
              >
                Copy file name
              </DropdownMenuItem>
            </DropdownMenuContent>
          </DropdownMenu>
          <div className="flex items-center gap-1">
            <span className="px-2 text-xs text-muted-foreground tabular-nums">
              Page 1 of 1
            </span>
            <Button
              variant="ghost"
              size="icon"
              className="size-8"
              aria-label="Zoom out"
              disabled={scale <= MIN_ZOOM}
              onClick={() => stepZoom(-0.1)}
            >
              <MinusIcon aria-hidden="true" className="size-4" />
            </Button>
            <span
              aria-live="polite"
              className="w-12 text-center text-xs tabular-nums"
            >
              {Math.round(scale * 100)}%
            </span>
            <Button
              variant="ghost"
              size="icon"
              className="size-8"
              aria-label="Zoom in"
              disabled={scale >= MAX_ZOOM}
              onClick={() => stepZoom(0.1)}
            >
              <PlusIcon aria-hidden="true" className="size-4" />
            </Button>
            <Button
              variant={zoom === null ? "secondary" : "ghost"}
              size="sm"
              aria-pressed={zoom === null}
              onClick={() => setZoom(null)}
            >
              Fit
            </Button>
          </div>
        </div>

        <div
          ref={box}
          tabIndex={0}
          role="region"
          aria-label="Document page"
          className="scroll-fade-effect-y scrollbar-none h-80 overflow-auto bg-muted p-4 outline-none focus-visible:ring-2 focus-visible:ring-ring focus-visible:ring-inset"
        >
          <div style={zoomStyle} className="mx-auto w-fit [zoom:var(--zoom)]">
            <InvoicePage lit={lit} filled={filled} />
          </div>
        </div>

        <Tabs
          value={tab}
          onValueChange={(value) => {
            setTab(TABS.find((item) => item === value) ?? "fields");
            setLit(null);
          }}

        >
          <div className="flex flex-wrap items-center justify-between gap-2 border-y border-border px-4 pt-2">
            <TabsList aria-label="Output">
              <TabsTrigger value="fields">Fields</TabsTrigger>
              <TabsTrigger value="json">JSON</TabsTrigger>
              <TabsTrigger value="schema">Schema</TabsTrigger>
            </TabsList>
            <Button
              size="sm"
              className="mb-2"
              disabled={run === "reading"}
              onClick={extract}
            >
              <SparklesIcon aria-hidden="true" className="size-4" />
              {run === "idle" ? "Extract" : "Extract again"}
            </Button>
          </div>
          <p role="status" className="px-4 pt-3 text-sm text-muted-foreground">
            {status}
          </p>
          <TabsContent value="fields">
            <div className="p-4">
            <FieldList
              filled={filled}
              confirmed={confirmed}
              lit={lit}
              onLight={setLit}
              onConfirm={confirm}
              register={register}
            />
            <div className="mt-4 flex flex-wrap justify-end gap-2">
              <Button
                size="sm"
                variant="outline"
                disabled={filled.size === 0 || run === "accepted"}
                onClick={review}
              >
                Review
              </Button>
              <Button size="sm" disabled={run !== "done"} onClick={acceptAll}>
                Accept all
              </Button>
            </div>
            </div>
          </TabsContent>
          <TabsContent value="json">
            <div className="p-4">
            <pre className="max-h-80 overflow-auto rounded-lg border border-border p-3 font-mono text-xs leading-relaxed">
              {toJson(filled)}
            </pre>
            </div>
          </TabsContent>
          <TabsContent value="schema">
            <div className="p-4">
            <pre className="max-h-80 overflow-auto rounded-lg border border-border p-3 font-mono text-xs leading-relaxed">
              {SCHEMA}
            </pre>
            </div>
          </TabsContent>
        </Tabs>

        <SourceConnector path={lit ? path : null} runKey={lit} />
      </div>
    </BlockFrame>
  );
}

"use client";

import { createContext, type ReactNode, type SVGProps, useContext } from "react";

import { cn } from "@/lib/utils";

import { FALLBACK_GLYPHS } from "./glyphs";
import type { BlockIconGlyphs, BlockIconName } from "./icon-names";

export type { BlockIconGlyphs, BlockIconName } from "./icon-names";

const GlyphContext = createContext<BlockIconGlyphs>(FALLBACK_GLYPHS);

/**
 * Hands the blocks under it the icons of one open-source pack. With no
 * provider, a block draws the glyphs in `./glyphs`: none on this site, which
 * always supplies a pack, and one open-source pack in an installed copy.
 */
export function BlockIconProvider({ glyphs, children }: { glyphs: BlockIconGlyphs; children: ReactNode }) {
  return <GlyphContext.Provider value={glyphs}>{children}</GlyphContext.Provider>;
}

/**
 * Makes an icon drawn from the chosen pack. Every name in `BLOCK_ICON_NAMES` is available. `turn` rotates the pack's glyph when the
 * pack has only one direction of it, such as an up arrow.
 */
export function packIcon(name: BlockIconName, turn?: string) {
  return function BlockIcon({ className, ...props }: SVGProps<SVGSVGElement>) {
    const glyph = useContext(GlyphContext)[name];
    return glyph ? <svg {...glyph} {...props} className={cn(turn, className)} /> : null;
  };
}

/** An icon no pack supplies, drawn here as plain strokes in the current colour. */
export function ownIcon(paths: ReactNode) {
  return function BlockIcon(props: SVGProps<SVGSVGElement>) {
    return (
      <svg
        aria-hidden="true"
        focusable="false"
        width="16"
        height="16"
        viewBox="0 0 16 16"
        fill="none"
        stroke="currentColor"
        strokeWidth="1.5"
        strokeLinecap="round"
        strokeLinejoin="round"
        {...props}
      >
        {paths}
      </svg>
    );
  };
}

/** A warning triangle, from the chosen icon pack. */
export const AlertTriangleIcon = packIcon("alert-triangle");
/** An arrow that points down, from the chosen icon pack. */
export const ArrowDownIcon = packIcon("arrow-up", "rotate-180");
