import type { ComponentPropsWithoutRef } from "react";

import { cn } from "@/lib/utils";

/**
 * The surface every block sits on: one bordered card that names itself to
 * screen readers through `aria-label` or `aria-labelledby`.
 */
export function BlockFrame({ className, ...props }: ComponentPropsWithoutRef<"section">) {
  return (
    <section
      {...props}
      className={cn(
        "@container w-full overflow-hidden rounded-2xl border border-border bg-card text-card-foreground shadow-sm",
        className,
      )}
    />
  );
}

/** One value the model reads off the page. Its `id` also names the span on the page it came from. */
export interface ExtractField {
  id: string;
  label: string;
  value: string;
  /** Fields in a line item share a row number. */
  row?: number;
  /** The JSON key of the field, or of the column inside a line item. */
  key: string;
}

/** The file name shown in the toolbar. */
export const FILE_NAME = "brackenwood-invoice-2291.pdf";

/** The fields, in the order the model reads them. */
export const FIELDS: ExtractField[] = [
  { id: "supplier", key: "supplier", label: "Supplier", value: "Brackenwood Medical Supply Co." },
  { id: "invoice_number", key: "invoice_number", label: "Invoice number", value: "BW-2291" },
  { id: "issue_date", key: "issue_date", label: "Issue date", value: "2026-10-14" },
  { id: "due_date", key: "due_date", label: "Due date", value: "2026-11-13" },
  { id: "bill_to", key: "bill_to", label: "Bill to", value: "Fernhill Clinics Ltd" },
  { id: "po_number", key: "po_number", label: "Purchase order", value: "FH-PO-0387" },
  { id: "item1_desc", key: "description", label: "Description", value: "Nitrile exam gloves, box of 200", row: 1 },
  { id: "item1_qty", key: "quantity", label: "Quantity", value: "24", row: 1 },
  { id: "item1_amount", key: "amount", label: "Amount", value: "312.00", row: 1 },
  { id: "item2_desc", key: "description", label: "Description", value: "Couch roll, 50 m", row: 2 },
  { id: "item2_qty", key: "quantity", label: "Quantity", value: "40", row: 2 },
  { id: "item2_amount", key: "amount", label: "Amount", value: "236.00", row: 2 },
  { id: "item3_desc", key: "description", label: "Description", value: "Thermometer probe covers", row: 3 },
  { id: "item3_qty", key: "quantity", label: "Quantity", value: "12", row: 3 },
  { id: "item3_amount", key: "amount", label: "Amount", value: "84.00", row: 3 },
  { id: "subtotal", key: "subtotal", label: "Subtotal", value: "632.00" },
  { id: "tax", key: "tax", label: "Tax at 8%", value: "50.56" },
  { id: "total", key: "total", label: "Total due", value: "682.56" },
];

/** The fields outside the line items. */
export const HEADER_FIELDS = FIELDS.filter((field) => field.row === undefined);

/** The line item numbers, in order. */
export const ROWS = [1, 2, 3];

/** The schema the run fills, shown on the Schema tab. */
export const SCHEMA = `{
  "type": "object",
  "properties": {
    "supplier": { "type": "string" },
    "invoice_number": { "type": "string" },
    "issue_date": { "type": "string", "format": "date" },
    "due_date": { "type": "string", "format": "date" },
    "bill_to": { "type": "string" },
    "po_number": { "type": "string" },
    "line_items": {
      "type": "array",
      "items": {
        "type": "object",
        "properties": {
          "description": { "type": "string" },
          "quantity": { "type": "integer" },
          "amount": { "type": "number" }
        }
      }
    },
    "subtotal": { "type": "number" },
    "tax": { "type": "number" },
    "total": { "type": "number" }
  }
}`;

/** The filled fields as the JSON a run returns. Fields not read yet are null. */
export function toJson(filled: Set<string>): string {
  const read = (field: ExtractField) => (filled.has(field.id) ? field.value : null);
  const numeric = (field: ExtractField) => {
    const value = read(field);
    return value === null ? null : Number(value);
  };
  const body = {
    ...Object.fromEntries(
      HEADER_FIELDS.map((field) => [field.key, ["subtotal", "tax", "total"].includes(field.key) ? numeric(field) : read(field)]),
    ),
    line_items: ROWS.map((row) =>
      Object.fromEntries(
        FIELDS.filter((field) => field.row === row).map((field) => [field.key, field.key === "description" ? read(field) : numeric(field)]),
      ),
    ),
  };
  return JSON.stringify(body, null, 2);
}

"use client";

import { Table, TableBody, TableCell, TableHead, TableHeader, TableRow } from "@/components/ui/table";

import { FIELDS, HEADER_FIELDS, ROWS } from "./data";
import { FieldValue, type FieldValueProps } from "./field-value";

/** Props for the list of fields to fill. */
export interface FieldListProps {
  filled: Set<string>;
  confirmed: Set<string>;
  lit: string | null;
  onLight: FieldValueProps["onLight"];
  onConfirm: FieldValueProps["onConfirm"];
  register: FieldValueProps["register"];
}

const COLUMNS = ["Description", "Quantity", "Amount"];

/** The header fields as label and value rows, then the line items as a table of cells. */
export function FieldList({ filled, confirmed, lit, onLight, onConfirm, register }: FieldListProps) {
  const cell = (id: string, name: string) => {
    const field = FIELDS.find((item) => item.id === id)!;
    return (
      <FieldValue
        field={field}
        name={name}
        filled={filled.has(id)}
        confirmed={confirmed.has(id)}
        lit={lit === id}
        onLight={onLight}
        onConfirm={onConfirm}
        register={register}
      />
    );
  };

  const head = HEADER_FIELDS.filter((field) => !["subtotal", "tax", "total"].includes(field.id));
  const sums = HEADER_FIELDS.filter((field) => ["subtotal", "tax", "total"].includes(field.id));

  return (
    <div className="flex flex-col gap-4">
      <dl className="grid gap-x-4 gap-y-2 @lg:grid-cols-2">
        {head.map((field) => (
          <div key={field.id} className="flex min-w-0 items-center justify-between gap-2">
            <dt className="shrink-0 text-xs text-muted-foreground">{field.label}</dt>
            <dd className="min-w-0">{cell(field.id, field.label)}</dd>
          </div>
        ))}
      </dl>

      <div className="overflow-hidden rounded-lg border border-border">
        <Table className="min-w-md caption-top">
          <caption className="border-b border-border px-3 py-2 text-left text-xs font-medium">Line items</caption>
          <TableHeader>
            <TableRow>
              {COLUMNS.map((column) => (
                <TableHead key={column} scope="col">
                  <span className="text-xs font-normal text-muted-foreground">{column}</span>
                </TableHead>
              ))}
            </TableRow>
          </TableHeader>
          <TableBody>
            {ROWS.map((row) => (
              <TableRow key={row}>
                <TableCell className="max-w-56">{cell(`item${row}_desc`, `Line ${row} description`)}</TableCell>
                <TableCell>{cell(`item${row}_qty`, `Line ${row} quantity`)}</TableCell>
                <TableCell>{cell(`item${row}_amount`, `Line ${row} amount`)}</TableCell>
              </TableRow>
            ))}
          </TableBody>
        </Table>
      </div>

      <dl className="grid gap-x-4 gap-y-2 @lg:ml-auto @lg:w-1/2">
        {sums.map((field) => (
          <div key={field.id} className="flex items-center justify-between gap-2">
            <dt className="text-xs text-muted-foreground">{field.label}</dt>
            <dd>{cell(field.id, field.label)}</dd>
          </div>
        ))}
      </dl>
    </div>
  );
}

