/** Props for one extracted value and its confirm button. */
export interface FieldValueProps {
  field: ExtractField;
  filled: boolean;
  confirmed: boolean;
  lit: boolean;
  /** The name read with the value, such as "Line 2 amount". */
  name: string;
  onLight: (id: string | null) => void;
  onConfirm: (id: string) => void;
  register: (id: string, element: HTMLElement | null) => void;
}

/**
 * One value from the page. Hovering or focusing it lights its source on the
 * page. Before the run reaches it, it shows a placeholder bar.
 */
export function FieldValue({ field, filled, confirmed, lit, name, onLight, onConfirm, register }: FieldValueProps) {
  if (!filled) {
    return (
      <span className="flex h-8 items-center px-2">
        <span aria-hidden="true" className="h-2 w-16 rounded-full bg-muted" />
        <span className="sr-only">{name}: not read yet</span>
      </span>
    );
  }
  return (
    <span className="flex min-w-0 items-center gap-0.5">
      <span className="flex min-w-0 motion-safe:animate-in motion-safe:fade-in">
      <Button
        ref={(element) => register(field.id, element)}
        variant={lit ? "secondary" : "ghost"}
        size="sm"
        aria-label={`${name}: ${field.value}. Show its source on the page`}
        onPointerEnter={() => onLight(field.id)}
        onPointerLeave={() => onLight(null)}
        onFocus={() => onLight(field.id)}
        onBlur={() => onLight(null)}
        onClick={() => onLight(field.id)}
        className="min-w-0 justify-start"
      >
        <span className="truncate">{field.value}</span>
      </Button>
      </span>
      <Button
        variant={confirmed ? "ghost" : "ghost"}
        size="icon"
        aria-pressed={confirmed}
        aria-label={`Confirm ${name}`}
        onClick={() => onConfirm(field.id)}
        className="size-7 shrink-0"
      >
        {confirmed ? <CircleCheckIcon aria-hidden="true" className={cn("size-4", STATUS_TEXT.good)} /> : <CheckIcon aria-hidden="true" className="size-4" />}
      </Button>
    </span>
  );
}

