"use client";

import { motion, useReducedMotion } from "motion/react";

/** Props for the curve between a field and its source. */
export interface SourceConnectorProps {
  /** The SVG path in the block's own coordinates, or null when nothing is lit. */
  path: string | null;
  /** Changes with each newly lit field, so the band of light runs once per field. */
  runKey: string | null;
}

/**
 * One curved line from a field up to its source on the page, drawn over the
 * whole block. A short band of light travels along it once. With reduced
 * motion the line simply appears and no band runs.
 */
export function SourceConnector({ path, runKey }: SourceConnectorProps) {
  const reduceMotion = useReducedMotion();
  if (!path) return null;
  return (
    <svg aria-hidden="true" className="pointer-events-none absolute inset-0 z-10 size-full overflow-visible text-chart-1">
      <motion.path
        key={`line-${runKey}`}
        d={path}
        fill="none"
        stroke="currentColor"
        strokeWidth={1.5}
        strokeLinecap="round"
        opacity={0.7}
        initial={reduceMotion ? false : { pathLength: 0 }}
        animate={{ pathLength: 1 }}
        transition={{ duration: 0.3, ease: "easeOut" }}
      />
      {reduceMotion ? null : (
        <motion.path
          key={`band-${runKey}`}
          d={path}
          fill="none"
          stroke="currentColor"
          strokeWidth={3.5}
          strokeLinecap="round"
          initial={{ pathLength: 0.12, pathOffset: 0, opacity: 0 }}
          animate={{ pathOffset: 0.88, opacity: [0, 1, 1, 0] }}
          transition={{ duration: 0.9, ease: "easeInOut", delay: 0.2 }}
        />
      )}
    </svg>
  );
}

